import requests

def fetch_user_profile(access_token):
    headers = {
        'Authorization': f'Bearer {access_token}'
    }
    response = requests.get('https://oauth.provider.com/userinfo', headers=headers)
    response.raise_for_status()
    user_profile = response.json()
    return {
        'sub': user_profile.get('sub'),
        'name': user_profile.get('name'),
        'email': user_profile.get('email')
    }

from typing import Dict

def normalize_user_profile(user_profile: Dict) -> Dict:
    return {
        'sub': user_profile.get('sub'),
        'name': user_profile.get('name'),
        'email': user_profile.get('email')
    }

def summarize_audit_events(events):
    summary = {
        'total_events': len(events),
        'success_count': sum(1 for event in events if event['status'] == 'success'),
        'failure_count': sum(1 for event in events if event['status'] == 'failure')
    }
    return summary

def moderate_claims(claims):
    moderated_claims = {
        key: value for key, value in claims.items() if key not in ['sensitive_info']
    }
    return moderated_claims

import boto3

def store_audit_record(record):
    client = boto3.client('dynamodb')
    client.put_item(
        TableName='FederatedLoginAudit',
        Item={
            'event_id': {'S': record['event_id']},
            'timestamp': {'S': record['timestamp']},
            'status': {'S': record['status']}
        }
    )
